begin;
select no_plan();
select ok(has_column_privilege('authenticated','public.orders','order_sequence','select'),'authenticated order history may read the sequence under existing row policies');
select ok(not has_column_privilege('anon','public.orders','order_sequence','select'),'anonymous users cannot select order sequences directly');
create temp table seq_ids as select gen_random_uuid() artist, gen_random_uuid() owner, gen_random_uuid() event_a, gen_random_uuid() event_b, gen_random_uuid() campaign, gen_random_uuid() first_order, gen_random_uuid() second_order, gen_random_uuid() other_order, gen_random_uuid() campaign_order;
insert into auth.users(id,email) select owner,'sequence-owner@example.local' from seq_ids;
insert into public.artists(id,slug,display_name) select artist,'sequence-test','Sequence test' from seq_ids;
insert into public.artist_members(artist_id,member_email,role,status) select artist,'sequence-owner@example.local','owner','active' from seq_ids;
insert into public.events(id,artist_id,event_name,start_date,end_date,status)
select event_a,artist,'Event A',now(),now()+interval '1 day','Confirmed' from seq_ids union all select event_b,artist,'Event B',now(),now()+interval '1 day','Confirmed' from seq_ids;
insert into public.online_campaigns(id,artist_id,name,slug,opens_at,closes_at) select campaign,artist,'Campaign','sequence-campaign',now(),now()+interval '1 day' from seq_ids;
insert into public.orders(id,event_id) select first_order,event_a from seq_ids;
insert into public.orders(id,event_id) select second_order,event_a from seq_ids;
insert into public.orders(id,event_id) select other_order,event_b from seq_ids;
insert into public.orders(id,campaign_id,order_type) select campaign_order,campaign,'online_sale' from seq_ids;
select is((select order_sequence from public.orders where id=(select first_order from seq_ids)),1::bigint,'first event order is 1');
select is((select order_sequence from public.orders where id=(select second_order from seq_ids)),2::bigint,'second event order is 2');
select is((select order_sequence from public.orders where id=(select other_order from seq_ids)),1::bigint,'other event has independent sequence');
select is((select order_sequence from public.orders where id=(select campaign_order from seq_ids)),1::bigint,'campaign has independent sequence');
delete from public.orders where id=(select second_order from seq_ids);
insert into public.orders(event_id) select event_a from seq_ids;
select is((select max(order_sequence) from public.orders where event_id=(select event_a from seq_ids)),3::bigint,'deleted number is not reused');
select throws_ok($$update public.orders set order_sequence=99 where id=(select first_order from seq_ids)$$,'order_scope_immutable','sequence cannot be edited');
select set_config('request.jwt.claims',jsonb_build_object('sub',owner,'email','sequence-owner@example.local','role','authenticated')::text,true) from seq_ids;
select is((select count(*) from public.get_order_sequences(array[(select first_order from seq_ids)])),1::bigint,'owner can read sequence');
select set_config('request.jwt.claims',jsonb_build_object('sub',gen_random_uuid(),'role','authenticated')::text,true);
select is((select count(*) from public.get_order_sequences(array[(select first_order from seq_ids)])),0::bigint,'other users cannot read sequence');
select * from finish();
rollback;
